template<class T>std::vector<T>readfile(const char*name,int n){std::vector<T>v(n);FILE*f=fopen(name,"rb");if(!f||fread(v.data(),sizeof(T),n,f)!=size_t(n)){fprintf(stderr,"Bad file %s\n",name);exit(3);}fclose(f);return v;}
